import path from 'node:path';
import os from 'node:os';

export const DIST_DIR = path.resolve(__dirname);
export const BASE_BIN_NAME = 'tgo-test';

const OS_NAME = os.platform(); // one of: 'darwin', 'linux', 'win32'
const ARCH_NAME = os.arch(); // one of: 'arm64', 'x64'

export const BIN_NAME_WITH_OS_ARCH = `${BASE_BIN_NAME}-${OS_NAME}-${ARCH_NAME}`;

export const TengoTesterBinaryPath = OS_NAME === 'win32' ?
    path.join(DIST_DIR, `${BIN_NAME_WITH_OS_ARCH}.exe`) :
    path.join(DIST_DIR, BIN_NAME_WITH_OS_ARCH);
